using System.Diagnostics;
using System.Text;
using System.Text.Json;
using System.Net;
ApplicationConfiguration.Initialize();
using var single=new Mutex(true,"MewRunJournal.User",out var first);
if(!first){MessageBox.Show("出征日记已经在运行，请用 Alt+Tab 切换到它。","出征日记");return;}
Application.Run(new Journal());
record SaveChoice(string Name,string Path){public override string ToString()=>Name;}
class Journal:Form {
 readonly JsonElement settings=JsonDocument.Parse(File.ReadAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"settings.json"))).RootElement.Clone();
 readonly Dictionary<string,string> labels=JsonSerializer.Deserialize<Dictionary<string,string>>(File.ReadAllText(System.IO.Path.Combine(AppContext.BaseDirectory,"labels.json")))!;
 readonly Dictionary<string,string> classes=new(){{"colorless","无职业"},{"fighter","战士"},{"hunter","猎手"},{"mage","法师"},{"medic","牧师"},{"tank","坦克"},{"thief","盗贼"},{"necromancer","死灵法师"},{"monk","武僧"},{"butcher","屠户"},{"druid","德鲁伊"},{"tinkerer","工匠"},{"psychic","灵能士"},{"jester","小丑"}};
 readonly ComboBox saves=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=150};
 readonly ComboBox outcome=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=170};
 readonly Label status=new(){AutoSize=true};
 readonly ListView list=new(){Dock=DockStyle.Fill,View=View.Details,FullRowSelect=true,MultiSelect=false,HideSelection=false};
 readonly TextBox detail=new(){Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Font=new Font("Microsoft YaHei UI",10)};
 readonly System.Windows.Forms.Timer timer=new(){Interval=3000};
 readonly Button mark=new(){Text="保存结果标注",AutoSize=true};
 bool busy;string signature="";int ticks;JsonElement[] records=Array.Empty<JsonElement>();
 string SavePath=>((SaveChoice)saves.SelectedItem!).Path;
 long? Selected=>list.SelectedItems.Count>0?(long)list.SelectedItems[0].Tag!:null;
 public Journal(){
  Text="喵喵的结合 · 出征日记";Size=new Size(1200,830);MinimumSize=new Size(1000,700);StartPosition=FormStartPosition.CenterScreen;Font=new Font("Microsoft YaHei UI",10);BackColor=Color.FromArgb(242,245,249);
  var root=new TableLayoutPanel(){Dock=DockStyle.Fill,Padding=new Padding(22),ColumnCount=1,RowCount=6};Controls.Add(root);
  root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
  root.Controls.Add(new Label(){Text="出征日记",Font=new Font(Font.FontFamily,23,FontStyle.Bold),AutoSize=true,Margin=new Padding(0,0,0,12)},0,0);
  var toolbar=new FlowLayoutPanel(){Dock=DockStyle.Fill,AutoSize=true,WrapContents=true};toolbar.Controls.Add(new Label(){Text="监控存档",AutoSize=true,Padding=new Padding(0,5,5,0)});toolbar.Controls.Add(saves);
  foreach(var s in settings.GetProperty("saves").EnumerateArray())saves.Items.Add(new SaveChoice(s.GetProperty("name").GetString()!,s.GetProperty("path").GetString()!));
  saves.SelectedIndex=2;
  var refresh=new Button(){Text="立即刷新",AutoSize=true};var export=new Button(){Text="导出当前记录",AutoSize=true};var folder=new Button(){Text="打开记录目录",AutoSize=true};toolbar.Controls.Add(refresh);toolbar.Controls.Add(export);toolbar.Controls.Add(folder);root.Controls.Add(toolbar,0,1);
  status.Margin=new Padding(0,8,0,12);status.Text="正在读取存档…";root.Controls.Add(status,0,2);
  var split=new SplitContainer(){Dock=DockStyle.Fill,Size=new Size(1120,500),SplitterDistance=620,Panel1MinSize=440,Panel2MinSize=300};split.Panel1.Controls.Add(list);split.Panel2.Controls.Add(detail);root.Controls.Add(split,0,3);
  list.Columns.Add("首次观察时间",150);list.Columns.Add("结果",190);list.Columns.Add("出征猫咪",400);
  var bottom=new FlowLayoutPanel(){Dock=DockStyle.Fill,AutoSize=true,Padding=new Padding(0,12,0,8)};bottom.Controls.Add(new Label(){Text="本次结果",AutoSize=true,Padding=new Padding(0,6,5,0)});outcome.Items.AddRange(new object[]{"待确认","胜利／通关","撤退回家","团灭","回档／放弃"});outcome.SelectedIndex=0;bottom.Controls.Add(outcome);bottom.Controls.Add(mark);root.Controls.Add(bottom,0,4);
  root.Controls.Add(new Label(){Text="保持本程序开启，自动保存时记录。只读取游戏存档，日记另存。\r\n未能确认的胜负会显示“待确认”，结束后可手动标注；关闭窗口即停止监控。",AutoSize=true,ForeColor=Color.DimGray,Margin=new Padding(0,5,0,0)},0,5);
  list.SelectedIndexChanged+=(_,_)=>ShowSelected();refresh.Click+=async(_,_)=>await Poll(true);saves.SelectedIndexChanged+=async(_,_)=>{signature="";await Poll(true);};export.Click+=(_,_)=>Export();folder.Click+=(_,_)=>{var p=System.IO.Path.Combine(AppContext.BaseDirectory,"记录");Directory.CreateDirectory(p);Process.Start(new ProcessStartInfo(p){UseShellExecute=true});};
  mark.Click+=async(_,_)=>{if(busy||Selected is not long id)return;busy=true;try{var r=await Call(new{action="set_result",save=SavePath,id,result=outcome.SelectedItem!.ToString()});Render(r,id);}catch(Exception e){status.Text=e.Message;}finally{busy=false;}};
  timer.Tick+=async(_,_)=>await Poll(false);Shown+=async(_,_)=>{await Poll(true);timer.Start();};FormClosed+=(_,_)=>timer.Stop();
 }
 async Task<JsonElement> Call(object request){var temp=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"mew-journal-"+Guid.NewGuid()+".json");File.WriteAllText(temp,JsonSerializer.Serialize(request),new UTF8Encoding(false));try{var pi=new ProcessStartInfo(settings.GetProperty("python").GetString()!){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=AppContext.BaseDirectory,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=Encoding.UTF8};pi.ArgumentList.Add("-X");pi.ArgumentList.Add("utf8");pi.ArgumentList.Add(System.IO.Path.Combine(AppContext.BaseDirectory,"backend.py"));pi.ArgumentList.Add(temp);using var p=Process.Start(pi)!;var output=p.StandardOutput.ReadToEndAsync();var err=p.StandardError.ReadToEndAsync();await p.WaitForExitAsync();var text=await output;var error=await err;var line=text.Split('\n',StringSplitOptions.RemoveEmptyEntries).LastOrDefault();if(line==null)throw new Exception(error.Length>0?error:"无法读取记录。");using var doc=JsonDocument.Parse(line);var r=doc.RootElement.Clone();if(!r.GetProperty("ok").GetBoolean())throw new Exception(r.GetProperty("error").GetString());return r;}finally{File.Delete(temp);}}
 async Task Poll(bool force){if(busy)return;var save=SavePath;string sig=save;foreach(var name in new[]{save,save+"-wal"}){var f=new FileInfo(name);if(f.Exists)sig+=$"|{f.Length}:{f.LastWriteTimeUtc.Ticks}";}if(!force&&sig==signature&&++ticks<10)return;busy=true;try{var r=await Call(new{action="poll",save});signature=r.GetProperty("message").GetString()!.StartsWith("等待")?"":sig;ticks=0;Render(r,Selected);}catch(Exception e){status.Text="读取暂缓："+e.Message;}finally{busy=false;}}
 string TextOf(JsonElement x,string key)=>x.TryGetProperty(key,out var v)&&v.ValueKind==JsonValueKind.String?v.GetString()!:"";
 string Time(string value)=>DateTimeOffset.TryParse(value,out var t)?t.ToString("MM-dd HH:mm:ss"):value;
 string Result(JsonElement r)=>r.TryGetProperty("manual",out var m)&&m.ValueKind==JsonValueKind.String?m.GetString()+"（手动）":TextOf(r,"result");
 void Render(JsonElement r,long? selected){if(TextOf(r,"message")!="")status.Text=TextOf(r,"message")+" · 只读监控";records=r.GetProperty("records").EnumerateArray().Select(x=>x.Clone()).ToArray();list.BeginUpdate();list.Items.Clear();foreach(var record in records){var id=record.GetProperty("id").GetInt64();var names=record.GetProperty("detail").GetProperty("startParty").EnumerateArray().Select(x=>TextOf(x,"name"));var item=new ListViewItem(Time(TextOf(record,"start"))){Tag=id};item.SubItems.Add(Result(record));item.SubItems.Add(string.Join("、",names));list.Items.Add(item);if(id==selected)item.Selected=true;}if(list.SelectedItems.Count==0&&list.Items.Count>0)list.Items[0].Selected=true;list.EndUpdate();if(records.Length==0){detail.Text="还没有观察到出征。\r\n\r\n保持本窗口开启，然后正常进入游戏出征即可。\r\n\r\n• 自动保存后记录队伍\r\n• 保存出征时的属性、技能和装备\r\n• 回家后保存猫咪的最终状态\r\n• 可补充胜利、撤退、团灭等结果\r\n\r\n程序未开启期间的出征无法保证补全。";mark.Enabled=false;}else ShowSelected();}
 string CatText(JsonElement cat){var b=new StringBuilder();var cls=TextOf(cat,"cat_class");b.AppendLine($"{TextOf(cat,"name")}  #{cat.GetProperty("key")}  {classes.GetValueOrDefault(cls.ToLowerInvariant(),cls)}");if(cat.TryGetProperty("missing",out var missing)&&missing.GetBoolean()){b.AppendLine("该猫已不在当前存档猫群中，未据此判定死亡。");return b.ToString();}b.AppendLine(StatsText.Describe(cat));if(cat.TryGetProperty("abilities",out var skills)&&skills.ValueKind==JsonValueKind.Array){var names=skills.EnumerateArray().Where(x=>x.ValueKind==JsonValueKind.String).Select(x=>x.GetString()!).Where(x=>x!="None"&&x!="").Distinct();b.AppendLine("技能："+string.Join("、",names.Select(x=>labels.GetValueOrDefault(x,x))));}if(cat.TryGetProperty("equipment",out var gear)){var items=gear.EnumerateArray().Select(x=>x.GetString()??"").Select(x=>x==""?"无":labels.GetValueOrDefault(x,x));b.AppendLine("装备："+string.Join(" / ",items));}if(cat.TryGetProperty("dead",out var dead)&&dead.ValueKind==JsonValueKind.True)b.AppendLine("状态：死亡");else if(cat.TryGetProperty("in_house",out var home)&&home.ValueKind==JsonValueKind.True)b.AppendLine("状态：家中");b.AppendLine();return b.ToString();}
 string Detail(JsonElement r){var d=r.GetProperty("detail");var b=new StringBuilder();b.AppendLine($"第 {r.GetProperty("id")} 次记录 · {Result(r)}");b.AppendLine("首次观察："+TextOf(r,"start"));b.AppendLine("结束观察："+(TextOf(r,"end")==""?"尚未结束":TextOf(r,"end")));b.AppendLine("游戏日期：第 "+d.GetProperty("startDay")+" 天");if(TextOf(d,"team")!="")b.AppendLine("队伍："+TextOf(d,"team"));b.AppendLine();if(d.TryGetProperty("preparation",out var preparation)){b.AppendLine("关联自定义方案："+TextOf(preparation,"title"));b.AppendLine("实际出征 "+d.GetProperty("startParty").GetArrayLength()+" 只，仅记录实际派出的成员。");b.AppendLine();}b.AppendLine("【出征阵容】");foreach(var cat in d.GetProperty("startParty").EnumerateArray())b.Append(CatText(cat));if(d.TryGetProperty("endParty",out var end)){b.AppendLine("【结束时状态】");foreach(var cat in end.EnumerateArray())b.Append(CatText(cat));b.AppendLine("【开始 → 结束属性变化】");var starts=d.GetProperty("startParty").EnumerateArray().ToDictionary(x=>x.GetProperty("key").GetInt64(),x=>x);foreach(var cat in end.EnumerateArray()){long key=cat.GetProperty("key").GetInt64();if(starts.TryGetValue(key,out var first)){b.AppendLine(TextOf(cat,"name")+" #"+key);b.AppendLine(StatsText.Compare(first,cat));b.AppendLine();}}}else if(d.TryGetProperty("latestParty",out var latest)){b.AppendLine("【最近观察状态（尚未结束）】");foreach(var cat in latest.EnumerateArray())b.Append(CatText(cat));}b.AppendLine("【观察日志】");foreach(var e in d.GetProperty("events").EnumerateArray())b.AppendLine(Time(TextOf(e,"time"))+" "+TextOf(e,"text"));return b.ToString();}
 void ShowSelected(){if(Selected is not long id)return;var r=records.FirstOrDefault(x=>x.GetProperty("id").GetInt64()==id);if(r.ValueKind!=JsonValueKind.Object)return;detail.Text=Detail(r);mark.Enabled=r.GetProperty("end").ValueKind==JsonValueKind.String;var manual=TextOf(r,"manual");outcome.SelectedItem=manual==""?"待确认":manual;}
 void Export(){try{var dir=System.IO.Path.Combine(AppContext.BaseDirectory,"记录");Directory.CreateDirectory(dir);var stem="出征日记-"+DateTime.Now.ToString("yyyyMMdd-HHmmss");var html=new StringBuilder("<!doctype html><meta charset='utf-8'><title>喵喵的结合 · 出征日记</title><style>body{max-width:1000px;margin:40px auto;font:16px/1.8 system-ui;background:#f4f6fa;color:#172437}article{background:white;padding:24px;margin:20px 0;border-radius:12px}pre{white-space:pre-wrap;font:inherit}</style><h1>出征日记</h1>");foreach(var r in records)html.Append("<article><pre>"+WebUtility.HtmlEncode(Detail(r))+"</pre></article>");var file=System.IO.Path.Combine(dir,stem+".html");File.WriteAllText(file,html.ToString(),new UTF8Encoding(false));File.WriteAllText(System.IO.Path.Combine(dir,stem+".json"),JsonSerializer.Serialize(records,new JsonSerializerOptions(){WriteIndented=true}),new UTF8Encoding(false));status.Text="已导出 "+records.Length+" 次记录："+file;Process.Start(new ProcessStartInfo(file){UseShellExecute=true});}catch(Exception e){status.Text=e.Message;}}
}
